    @Override
    public DrawnGift draw(String userId,
                          String username,
                          CertificateType certificateType,
                          String certificateNo,
                          Geo geo,
                          LocalDateTime drawingTime) {
        notBlank(userId, "User id is required!");
        notNull(geo, "Geo is required!");
        notNull(drawingTime, "Drawing time is required!");

        logger.info("Drawing for user {} with geo {} at {}", userId, geo, drawingTime);
        if (!open(geo, drawingTime)) {
            logger.warn("Condition mismatched for user {}, geo {}. drawing time {}",
                    userId, geo, drawingTime);
            throw new DrawnGiftNotAvailableException(String.format("Geo %s or drawing time %s not matched with user id %s!", geo, drawingTime, username));
        }

        //user id 加分布式锁
        LockResult lockResult = redisLocker.lock(String.join("@", userId, "future"));

        try {
            //投保
            if (ThreadLocalRandom.current().nextDouble() < firstGiftProbability) {
                try {
                    return draw(userId, username, certificateType, certificateNo, geo, firstGiftPool, drawingTime);
                } catch (DrawnGiftExceededMaxPerUserException e) {
                    //已经投过保险了
                    logger.info("Will try second draw for user {}-{}, geo {}, drawing time {}!", username, userId, geo, drawingTime);
                    if (logger.isTraceEnabled()) {
                        logger.trace("Will try second draw!", e);
                    }
                }
            }

            //已经投过保险了
            //有 secondGiftProbability 机会进行第二个奖品的抽奖
            List<DrawnGift> totalGifts =
                    drawnGiftRepository.findByUserGiftSetCode(userId,
                            firstGiftPool.getGiftSetCode(),
                            startDate.atStartOfDay(),
                            endDate.plusDays(1).atStartOfDay());
            if (defaultIfNull(totalGifts, Collections.EMPTY_LIST).size() >= 2) {
                throw new DrawnGiftExceededException(String.format("User %s with geo %s or drawing time %s failed with total time exceeded!", username, geo, drawingTime));
            }
            if (ThreadLocalRandom.current().nextDouble() < secondGiftProbability) {
                return draw(userId, username, certificateType, certificateNo, geo, secondGiftPool, drawingTime);
            }
            //第三个奖品中奖
            return draw(userId, username, certificateType, certificateNo, geo, thirdGiftPool, drawingTime);
        } catch (Exception e) {
            logger.error("Cannot draw for user {} with geo {} at {}", userId, geo, drawingTime, e);
            throw new DrawnGiftFailedException(String.format("User %s with geo %s or drawing time %s failed!", username, geo, drawingTime), e);
        } finally {
            redisLocker.unlock(lockResult.getKey(), lockResult.getValue());
        }
    }

    /**
     * @param userId
     * @param username
     * @param geo
     * @param giftPool
     * @param drawingTime
     * @return
     */
    private DrawnGift draw(String userId, String username, CertificateType certificateType, String certificateNo, Geo geo, GiftPool giftPool, LocalDateTime drawingTime) {
        List<DrawnGift> drawnGifts =
                drawnGiftRepository.findByGiftId(userId, giftPool.getId(),
                        startDate.atStartOfDay(),
                        endDate.plusDays(1).atStartOfDay());

        //中奖次数太多
        int hitCount = defaultIfNull(drawnGifts, Collections.emptyList()).size();
        if (hitCount >= giftPool.getMaxPerUser()) {
            logger.info("User {} hit too many gift({} out of {}) {}-{} at {}.", userId,
                    hitCount, giftPool.getMaxPerUser(),
                    giftPool.getGiftName(), giftPool.getGiftSetName(), drawingTime);

            throw new DrawnGiftExceededMaxPerUserException(String.format("User %s with geo %s or drawing time %s failed!", username, geo, drawingTime));
        }

        boolean available = giftPoolService.giftAvailable(giftPool.getId(), drawingTime);
        //奖池为空
        if (!available) {
            DrawnGift outOfStorage = drawnGiftRepository.save(new DrawnGift()
                    .outOfStorage(userId, giftPool, drawingTime)
                    .user(username, certificateType, certificateNo)
                    .geo(geo));
            logger.info("Gift {}@{} out of storage for user {} at {}:{}.",
                    giftPool.getGiftName(), giftPool.getGiftSetName(), userId, drawingTime, outOfStorage);
            return outOfStorage;
        }

        boolean drawn = giftPool.drawn();
        //未中奖
        if (!drawn) {
            DrawnGift missed = drawnGiftRepository.save(new DrawnGift()
                    .missed(userId, giftPool, drawingTime)
                    .user(username, certificateType, certificateNo)
                    .geo(geo));
            logger.info("User {} missed gift {}@{} at {}: {}",
                    userId, giftPool.getGiftName(), giftPool.getGiftSetName(), drawingTime, missed.describe());
            return missed;
        }

        //已中奖
        giftPoolService.decreaseGift(giftPool.getId(), drawingTime);
        DrawnGift hit = drawnGiftRepository.save(new DrawnGift()
                .hit(userId, giftPool, drawingTime)
                .user(username, certificateType, certificateNo)
                .geo(geo));
        logger.info("User {} hit gift {}@{} at {}:{}.",
                userId, giftPool.getGiftName(), giftPool.getGiftSetName(), drawingTime, hit.describe());
        return hit;
    }

